package com.nigson.acceptance.payment;

import java.util.*;
import java.time.*;
import java.net.*;
import java.net.http.*;
import org.springframework.context.ConfigurableApplicationContext;
import com.nigson.acceptance.order.OrderHttpAcceptance;
import com.nigson.commerce.payment.*;
import com.nigson.commerce.security.*;
import com.nigson.shared.events.EventCodec;
import static org.assertj.core.api.Assertions.*;

/** Actual BFF sessions, current finance roles and privately signed workload HTTP. */
public final class PaymentHttpAcceptance {
 private PaymentHttpAcceptance(){}
 public static final class Fixture implements AutoCloseable {
  public final OrderHttpAcceptance.Fixture fixture;
  public Fixture()throws Exception{fixture=new OrderHttpAcceptance.Fixture();}
  public void configure(Map<String,Object> p){fixture.configure(p);p.put("NIGSON_PAYMENT_ENABLED","true");p.put("NIGSON_PAYMENT_WORKER_ENABLED","false");p.put("NIGSON_PAYSTACK_INTEGRATION_ID","1");p.put("NIGSON_PAYMENT_RECEIPT_KEY_REVISION","synthetic-r1");byte[] key=new byte[32];new java.security.SecureRandom().nextBytes(key);p.put("NIGSON_PAYMENT_RECEIPT_LOCAL_KEY",Base64.getEncoder().encodeToString(key));}
  public void close(){var f=fixture.order;try{f.jdbc.update("DELETE FROM commerce.webhook_receipt WHERE merchant_account='SYNTHETIC_OFFLINE_MERCHANT'");f.jdbc.update("DELETE FROM commerce.refund_line WHERE refund_id IN(SELECT r.id FROM commerce.refund r JOIN commerce.sales_order o ON o.id=r.order_id WHERE o.market_id=?)",f.prices.market);f.jdbc.update("DELETE FROM commerce.refund WHERE order_id IN(SELECT id FROM commerce.sales_order WHERE market_id=?)",f.prices.market);}finally{fixture.close();}}
 }
 private record Browser(String cookie,String csrf){}
 private static Browser browser(JdbcSessionTrust sessions,com.nigson.acceptance.order.OrderFixture f,UUID party){String issuer=f.jdbc.queryForObject("SELECT identity_issuer FROM commerce.party WHERE id=?",String.class,party),subject=f.jdbc.queryForObject("SELECT identity_subject FROM commerce.party WHERE id=?",String.class,party);var flow=sessions.begin("/account");sessions.consume(flow.sessionId(),flow.flow().state());String csrf=JdbcSessionTrust.opaque();String id=sessions.authenticate(flow.sessionId(),new SessionRecord(1,party,issuer,subject,Instant.now(),Instant.now(),"synthetic-access","synthetic-refresh",Instant.now().plusSeconds(300),csrf,SessionRecord.TokenState.READY));return new Browser("__Host-nigson-session="+id,csrf);}
 private static HttpResponse<String> send(HttpClient http,HttpRequest.Builder request)throws Exception{return http.send(request.timeout(Duration.ofSeconds(30)).build(),HttpResponse.BodyHandlers.ofString());}
 private static HttpRequest.Builder get(String url,Browser b){return HttpRequest.newBuilder(URI.create(url)).header("Cookie",b.cookie()).GET();}
 private static HttpRequest.Builder command(String url,Browser b,String key,String body,long version){return HttpRequest.newBuilder(URI.create(url)).header("Cookie",b.cookie()).header("X-CSRF-TOKEN",b.csrf()).header("Idempotency-Key",key).header("If-Match","\""+version+"\"").header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(body));}
 private static HttpRequest.Builder privateCommand(String url,String token,String key,String body){return HttpRequest.newBuilder(URI.create(url)).header("Authorization","Bearer "+token).header("Idempotency-Key",key).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(body));}
 private static String signature(String body)throws Exception{var mac=javax.crypto.Mac.getInstance("HmacSHA512");mac.init(new javax.crypto.spec.SecretKeySpec("sk_mock_nigson".getBytes(java.nio.charset.StandardCharsets.UTF_8),"HmacSHA512"));return HexFormat.of().formatHex(mac.doFinal(body.getBytes(java.nio.charset.StandardCharsets.UTF_8)));}
 private static HttpRequest.Builder callback(String url,String body,String sig){return HttpRequest.newBuilder(URI.create(url)).header("Content-Type","application/json").header("X-Paystack-Signature",sig).POST(HttpRequest.BodyPublishers.ofString(body));}
 public static void run(ConfigurableApplicationContext app,HttpClient http,String base,Fixture fixture)throws Exception{
  if(fixture==null)return;var f=fixture.fixture.order;f.jdbc.update("UPDATE commerce.market SET enabled=true WHERE id=?",f.prices.market);var sessions=app.getBean(JdbcSessionTrust.class);var browsers=new ArrayList<Browser>();UUID secondRole=null;
  try{
   var customer=browser(sessions,f,f.prices.customer.party());var finance=browser(sessions,f,f.prices.finance.party());browsers.add(customer);browsers.add(finance);var checkout=f.checkout("payment-http");UUID order=checkout.order().id();String payment=base+"/api/v1/orders/"+order+"/payment",request=base+"/api/v1/staff/orders/"+order+"/refunds",callback=base+"/api/v1/webhooks/payments/paystack";
   assertThat(send(http,get(payment,customer)).statusCode()).isEqualTo(200);assertThat(EventCodec.JSON.readTree(send(http,get(payment,customer)).body()).path("settled").asBoolean()).isFalse();assertThat(send(http,get(payment,finance)).statusCode()).isEqualTo(404);assertThat(send(http,get(payment+"?poll=true",customer)).statusCode()).isEqualTo(400);
   String object=f.state().path("operations").path(checkout.payment().reference()).path("id").asString(),body=EventCodec.JSON.writeValueAsString(Map.of("event","charge.success","data",Map.of("id",object,"reference",checkout.payment().reference(),"domain","test")));
   assertThat(send(http,callback(callback,"{invalid","0".repeat(128))).statusCode()).isEqualTo(401);assertThat(send(http,callback(callback,body,signature(body)).header("Cookie",customer.cookie()).header("X-CSRF-TOKEN","wrong")).statusCode()).isEqualTo(200);assertThat(send(http,callback(callback,body,signature(body))).body()).isEqualTo("{\"received\":true}");assertThat(repository(app).payment(order).settled()).isFalse();assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.webhook_receipt WHERE state='RECEIVED'",Integer.class)).isEqualTo(1);f.progress(checkout,"success");UUID receipt=f.jdbc.queryForObject("SELECT id FROM commerce.webhook_receipt WHERE state='RECEIVED'",UUID.class);assertThat(app.getBean(PaymentReceiptProcessor.class).process(receipt,UUID.randomUUID())).isEqualTo("APPLIED");var paid=send(http,get(payment,customer));assertThat(paid.statusCode()).isEqualTo(200);assertThat(paid.headers().firstValue("Cache-Control")).hasValue("no-store");assertThat(EventCodec.JSON.readTree(paid.body()).path("settled").asBoolean()).isTrue();assertThat(paid.body()).doesNotContain("sk_mock","merchantAccount","provider_mode","synthetic-refresh");
   long version=f.service.get(f.prices.customer,order).version();String refundBody="{\"amount\":\"12.34\",\"reason\":\"Synthetic authorized financial refund\"}";assertThat(send(http,command(request,customer,"customer-denial",refundBody,version)).statusCode()).isEqualTo(403);assertThat(send(http,command(request,new Browser(finance.cookie(),"wrong"),"csrf-denial",refundBody,version)).statusCode()).isEqualTo(401);assertThat(send(http,command(request,finance,"invalid-money",refundBody.replace("12.34","12.340"),version)).statusCode()).isEqualTo(400);assertThat(send(http,command(request,finance,"stale-request",refundBody,version-1)).statusCode()).isEqualTo(412);
   var created=send(http,command(request,finance,"finance-request",refundBody,version));assertThat(created.statusCode()).as("refund request: %s",created.body()).isEqualTo(201);var refund=EventCodec.JSON.readTree(created.body());assertThat(refund.propertyNames()).containsExactlyInAnyOrder("id","state","amount","currency","version");String refundId=refund.path("id").asString(),approval=base+"/api/v1/staff/refunds/"+refundId+"/approval",detail=base+"/api/v1/staff/refunds/"+refundId;assertThat(created.headers().firstValue("ETag")).hasValue("\"0\"");assertThat(send(http,command(request,finance,"finance-request",refundBody,version)).body()).isEqualTo(created.body());String approve="{\"approve\":true,\"reason\":\"Synthetic separate finance approval\"}";assertThat(send(http,command(approval,finance,"self-approval",approve,0)).statusCode()).isEqualTo(403);
   secondRole=UUID.randomUUID();f.jdbc.update("INSERT INTO commerce.staff_role_assignment(id,created_by,updated_by,party_id,role,granted_by) VALUES (?,'test','test',?,'FINANCE',?)",secondRole,f.prices.customer.party(),f.prices.finance.party());var approved=send(http,command(approval,customer,"separate-approval",approve,0));assertThat(approved.statusCode()).as("refund approval: %s",approved.body()).isEqualTo(200);assertThat(EventCodec.JSON.readTree(approved.body()).path("state").asString()).isEqualTo("APPROVED");assertThat(send(http,command(request,finance,"finance-request",refundBody,version)).body()).contains("APPROVED");assertThat(send(http,get(detail,finance)).statusCode()).isEqualTo(200);assertThat(EventCodec.JSON.readTree(send(http,get(detail,finance)).body()).propertyNames()).containsExactlyInAnyOrder("id","state","amount","currency","version","providerReference");assertThat(EventCodec.JSON.readTree(send(http,get(detail,finance)).body()).path("providerReference").isNull()).isTrue();
   UUID refundUuid=UUID.fromString(refundId);app.getBean(RefundOperations.class).submit(refundUuid,UUID.randomUUID());String provider=f.jdbc.queryForObject("SELECT provider_refund_id FROM commerce.refund WHERE id=?",String.class,refundUuid);f.admin("progress",Map.of("id",provider,"status","processed"));String url=base+"/internal/v1/payments/reconciliation",reconcileBody=EventCodec.JSON.writeValueAsString(Map.of("jobId",UUID.randomUUID(),"limit",100));for(var invalid:List.of(List.of("payment.write","nigson-integration","nigson-commerce"),List.of("payment.reconcile","nigson-experience","nigson-commerce"),List.of("payment.reconcile","nigson-integration","nigson-experience"))){String token=fixture.fixture.workload.token(invalid.get(0),invalid.get(1),invalid.get(2));assertThat(send(http,privateCommand(url,token,"wrong-private",reconcileBody)).statusCode()).isEqualTo(401);}
   String token=fixture.fixture.workload.token("payment.reconcile","nigson-integration","nigson-commerce");var reconciled=send(http,privateCommand(url,token,"actual-reconcile",reconcileBody));assertThat(reconciled.statusCode()).as("reconciliation: %s",reconciled.body()).isEqualTo(202);assertThat(EventCodec.JSON.readTree(reconciled.body()).path("processed").asInt()).isEqualTo(1);assertThat(EventCodec.JSON.readTree(reconciled.body()).path("mismatches").asInt()).isZero();var journal=f.state().path("journal").deepCopy();assertThat(send(http,privateCommand(url,token,"actual-reconcile",reconcileBody)).body()).isEqualTo(reconciled.body());assertThat(f.state().path("journal")).isEqualTo(journal);assertThat(EventCodec.JSON.readTree(send(http,get(detail,finance)).body()).path("providerReference").asString()).isEqualTo(provider);assertThat(f.service.get(f.prices.customer,order).totals().refunded()).isEqualTo("12.34");assertThat(f.stock("allocated")).isEqualByComparingTo("2");f.jdbc.update("UPDATE commerce.staff_role_assignment SET revoked_at=now() WHERE id=?",secondRole);assertThat(send(http,command(approval,customer,"separate-approval",approve,0)).statusCode()).isEqualTo(403);
  }finally{if(secondRole!=null)f.jdbc.update("DELETE FROM commerce.staff_role_assignment WHERE id=?",secondRole);for(var b:browsers)sessions.logout(b.cookie().substring(b.cookie().indexOf('=')+1));}
 }
 private static PaymentRepository repository(ConfigurableApplicationContext app){return app.getBean(PaymentRepository.class);}
}
